import{c as i,Z as t,Q as l,j as s,g as e,n,o,m as u}from"./chunks/framework.BnKG8mJY.js";const q=JSON.parse('{"title":"Dashboard Overview","description":"","frontmatter":{"title":"Dashboard Overview","outline":"deep"},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),d={name:"guide/dashboard.md"},h={id:"dashboard-overview",tabindex:"-1"};function m(b,a,p,k,c,g){const r=t("Badge");return l(),s("div",null,[e("h1",h,[a[0]||(a[0]=n("Dashboard Overview ",-1)),o(r,{type:"tip",text:"^0.3"}),a[1]||(a[1]=n()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#dashboard-overview","aria-label":'Permalink to "Dashboard Overview <Badge type="tip" text="^0.3" />"'},"​",-1))]),a[3]||(a[3]=u('<h2 id="ringkasan-dashboard" tabindex="-1">Ringkasan Dashboard <a class="header-anchor" href="#ringkasan-dashboard" aria-label="Permalink to &quot;Ringkasan Dashboard&quot;">​</a></h2><p>Dashboard menampilkan ringkasan performa operasional dan finansial dalam satu layar. Informasi disusun agar pengguna dapat memantau tren, perbandingan biaya, serta aktivitas terbaru tanpa berpindah halaman.</p><h2 id="sales-cost-summary" tabindex="-1">Sales Cost Summary <a class="header-anchor" href="#sales-cost-summary" aria-label="Permalink to &quot;Sales Cost Summary&quot;">​</a></h2><p>Ringkasan Sales Cost memberikan gambaran kinerja penjualan dan biaya operasional.</p><h3 id="filter-bulan-tahun" tabindex="-1">Filter bulan &amp; tahun <a class="header-anchor" href="#filter-bulan-tahun" aria-label="Permalink to &quot;Filter bulan &amp; tahun&quot;">​</a></h3><ul><li>Pilih bulan dan tahun untuk melihat ringkasan periode tertentu.</li><li>Perubahan filter akan memperbarui nilai ringkasan secara otomatis.</li></ul><h3 id="indikator-persentase-perubahan" tabindex="-1">Indikator persentase perubahan <a class="header-anchor" href="#indikator-persentase-perubahan" aria-label="Permalink to &quot;Indikator persentase perubahan&quot;">​</a></h3><ul><li>Menampilkan perubahan Gross Profit dibanding periode sebelumnya.</li><li>Warna indikator membantu membaca tren naik atau turun.</li></ul><h2 id="subcontractor-summary" tabindex="-1">Subcontractor Summary <a class="header-anchor" href="#subcontractor-summary" aria-label="Permalink to &quot;Subcontractor Summary&quot;">​</a></h2><p>Ringkasan Subcontractor menampilkan total transaksi subcontractor dan pola tren biaya terkait.</p><h2 id="monthly-sales-transaction" tabindex="-1">Monthly Sales Transaction <a class="header-anchor" href="#monthly-sales-transaction" aria-label="Permalink to &quot;Monthly Sales Transaction&quot;">​</a></h2><p>Grafik transaksi bulanan menampilkan volume transaksi berdasarkan periode.</p><h3 id="grafik-bulanan" tabindex="-1">Grafik bulanan <a class="header-anchor" href="#grafik-bulanan" aria-label="Permalink to &quot;Grafik bulanan&quot;">​</a></h3><ul><li>Menunjukkan perbandingan Sales Cost dan Subcontractor per bulan.</li><li>Membantu identifikasi tren naik atau turun.</li></ul><h3 id="filter-tahun" tabindex="-1">Filter tahun <a class="header-anchor" href="#filter-tahun" aria-label="Permalink to &quot;Filter tahun&quot;">​</a></h3><ul><li>Tersedia filter tahun untuk menampilkan data historis.</li><li>Pergantian tahun akan memperbarui data grafik.</li></ul><h2 id="detail-sales-cost-monthly" tabindex="-1">Detail Sales Cost (Monthly) <a class="header-anchor" href="#detail-sales-cost-monthly" aria-label="Permalink to &quot;Detail Sales Cost (Monthly)&quot;">​</a></h2><p>Detail Sales Cost (Monthly) menampilkan angka kunci untuk periode terpilih:</p><ul><li>Sales</li><li>Total Cost</li><li>Gross Profit</li></ul><h2 id="truck-transaction-average" tabindex="-1">Truck Transaction Average <a class="header-anchor" href="#truck-transaction-average" aria-label="Permalink to &quot;Truck Transaction Average&quot;">​</a></h2><p>Bagian ini menampilkan jumlah transaksi yang diterima atau di assign ke masing-masing truck dalam 1 bulan</p><h3 id="persentase-chart" tabindex="-1">Persentase Chart <a class="header-anchor" href="#persentase-chart" aria-label="Permalink to &quot;Persentase Chart&quot;">​</a></h3><ul><li>Loading chart mengacu kepada persentase penggunaan truk dalam satu bulan</li></ul><blockquote><p>21/jumlah transaksi *100 = (menampilkan Persen)</p></blockquote><h2 id="calendar-event-list" tabindex="-1">Calendar Event List <a class="header-anchor" href="#calendar-event-list" aria-label="Permalink to &quot;Calendar Event List&quot;">​</a></h2><p>Daftar event kalender menampilkan aktivitas yang relevan dengan operasional.</p><h3 id="informasi-utama" tabindex="-1">Informasi utama <a class="header-anchor" href="#informasi-utama" aria-label="Permalink to &quot;Informasi utama&quot;">​</a></h3><ul><li>Event</li><li>Date/Time</li><li>Created by</li><li>Ownership</li></ul><h3 id="filter-see-all" tabindex="-1">Filter &amp; See All <a class="header-anchor" href="#filter-see-all" aria-label="Permalink to &quot;Filter &amp; See All&quot;">​</a></h3><ul><li>Filter periode untuk membatasi event yang tampil.</li><li>Tombol See All menuju halaman kalender lengkap.</li></ul><h2 id="filter-interaksi-dashboard" tabindex="-1">Filter &amp; Interaksi Dashboard <a class="header-anchor" href="#filter-interaksi-dashboard" aria-label="Permalink to &quot;Filter &amp; Interaksi Dashboard&quot;">​</a></h2><ul><li>Filter periode membantu fokus pada data yang relevan.</li><li>Komponen grafik dapat dipantau tanpa reload halaman.</li><li>Ringkasan dan statistik diperbarui mengikuti perubahan filter.</li></ul><h2 id="peran-pengguna" tabindex="-1">Peran Pengguna <a class="header-anchor" href="#peran-pengguna" aria-label="Permalink to &quot;Peran Pengguna&quot;">​</a></h2><p>Dashboard digunakan oleh beberapa peran berikut:</p><h3 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h3><p>Mengelola data dan memantau keseluruhan performa.</p><h3 id="manager" tabindex="-1">Manager <a class="header-anchor" href="#manager" aria-label="Permalink to &quot;Manager&quot;">​</a></h3><p>Memantau KPI, tren biaya, dan performa tim.</p><h3 id="finance" tabindex="-1">Finance <a class="header-anchor" href="#finance" aria-label="Permalink to &quot;Finance&quot;">​</a></h3><p>Menganalisis biaya, margin, dan tren profit.</p><h3 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h3><p>Memantau transaksi harian dan status pengiriman.</p><h2 id="tujuan-penggunaan-dashboard" tabindex="-1">Tujuan Penggunaan Dashboard <a class="header-anchor" href="#tujuan-penggunaan-dashboard" aria-label="Permalink to &quot;Tujuan Penggunaan Dashboard&quot;">​</a></h2><ul><li>Memberikan ringkasan cepat untuk pengambilan keputusan.</li><li>Menyajikan tren biaya dan pendapatan dalam satu tampilan.</li><li>Mempermudah pemantauan aktivitas operasional.</li></ul><h2 id="catatan-pengembangan" tabindex="-1">Catatan Pengembangan <a class="header-anchor" href="#catatan-pengembangan" aria-label="Permalink to &quot;Catatan Pengembangan&quot;">​</a></h2><ul><li>Pastikan data backend konsisten agar grafik tetap akurat.</li><li>Tambahkan validasi jika ada perubahan skema data.</li><li>Dokumentasikan perubahan indikator jika ada penyesuaian bisnis.</li></ul>',46))])}const P=i(d,[["render",m]]);export{q as __pageData,P as default};
